#!/usr/bin/env node

/**
 * Build the small, reviewable Synthea fixture used by the browser demo.
 *
 * Usage:
 *   node scripts/curate-synthea-bundle.mjs input.json output.json
 *
 * The input remains an unmodified Synthea patient Bundle. We retain the
 * patient's current clinical data and recent results while omitting claims,
 * EOBs, and other resources Parthia does not use. fullUrl values are kept so
 * urn:uuid references continue to resolve exactly as they do in the source.
 */
import { readFile, writeFile } from "node:fs/promises";

const [inputPath, outputPath] = process.argv.slice(2);
if (!inputPath || !outputPath) {
  throw new Error("Usage: node scripts/curate-synthea-bundle.mjs input.json output.json");
}

const bundle = JSON.parse(await readFile(inputPath, "utf8"));
const entries = bundle.entry ?? [];
const byFullUrl = new Map(entries.map((entry) => [entry.fullUrl, entry]));
const selected = new Set();

const resourceDate = (resource) =>
  resource.effectiveDateTime ??
  resource.authoredOn ??
  resource.recordedDate ??
  resource.performedDateTime ??
  resource.performedPeriod?.start ??
  resource.occurrenceDateTime ??
  resource.occurrencePeriod?.start ??
  resource.period?.start ??
  resource.date ??
  "";

const isActiveCondition = (resource) =>
  resource.clinicalStatus?.coding?.some((coding) => coding.code === "active");

const include = (entry) => {
  if (entry) selected.add(entry);
};

for (const entry of entries) {
  const resource = entry.resource;
  switch (resource.resourceType) {
    case "Patient":
    case "AllergyIntolerance":
      include(entry);
      break;
    case "Condition":
      if (isActiveCondition(resource)) include(entry);
      break;
    case "MedicationRequest":
      if (resource.status === "active") {
        include(entry);
        include(byFullUrl.get(resource.medicationReference?.reference));
      }
      break;
    case "Observation":
    case "DiagnosticReport":
    case "Encounter":
    case "DocumentReference":
    case "Procedure":
    case "Immunization":
      if (resourceDate(resource) >= "2025-01-01") include(entry);
      break;
    case "CarePlan":
      if (resource.status === "active") include(entry);
      break;
    case "CareTeam":
      if (resource.status === "active") include(entry);
      break;
  }
}

// Pull in directly referenced resources used by selected reports and care teams.
for (const entry of [...selected]) {
  const resource = entry.resource;
  const references = [
    ...(resource.result ?? []),
    ...(resource.participant ?? []).map((participant) => participant.member),
    ...(resource.careTeam ?? []),
  ];
  for (const reference of references) include(byFullUrl.get(reference?.reference));
}

const output = {
  resourceType: "Bundle",
  id: "parthia-synthea-shaun-curated",
  type: "collection",
  timestamp: bundle.timestamp,
  meta: {
    source: "https://synthea.mitre.org/",
    tag: [
      {
        system: "https://parthia.health/fhir/tags",
        code: "synthetic-demo-data",
        display: "Synthetic demo data generated by Synthea",
      },
    ],
  },
  entry: entries.filter((entry) => selected.has(entry)),
};

await writeFile(outputPath, `${JSON.stringify(output, null, 2)}\n`);
console.log(`Wrote ${output.entry.length} resources to ${outputPath}`);
